def is_level_complete(grid):
    """
    Checks if the grid is in a win state.
    The win condition for cn04 is that all cells in the grid are the same color.
    """
    grid = np.array(grid)
    if grid.size == 0:
        return False

    # Check if all elements are the same
    return np.all(grid == grid[0, 0])

