def is_level_complete(grid):
    """
    Checks if the grid is in a win state.
    The win condition is that all cells are the same color (excluding background 0).
    """
    grid = np.array(grid)
    non_zero = grid[grid != 0]
    if non_zero.size == 0:
        return False
    return np.all(non_zero == non_zero[0])
